+          { id: "javascript", label: "JavaScript", detail: "The standard scripting language supported by browsers.", correct: true },
+          { id: "typescript", label: "TypeScript", detail: "Usually compiled to JavaScript before running in browsers.", correct: false },
+          { id: "webassembly", label: "WebAssembly", detail: "A low-level language format supported by modern browsers.", correct: true },
+          { id: "csharp", label: "C#", detail: "Typically needs a runtime or compilation target for browser execution.", correct: false }
