  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a31;
      --panel-strong: #18223d;
      --text: #f6f8ff;
      --muted: #b8c2d8;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --success: #86efac;
