      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: 0.84rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 4rem);
      line-height: 1.05;
    }

    .intro {
      max-width: 42rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.08rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: linear-gradient(180deg, rgba(24, 34, 61, 0.96), rgba(18, 26, 49, 0.96));
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      float: left;
      width: 100%;
      margin-bottom: 0.35rem;
      font-size: 1.18rem;
      font-weight: 800;
    }

    .help-text {
      clear: both;
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .choices {
      clear: both;
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

