<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Multiple-answer quiz</p>
      <h1 id="quiz-title">Computer Languages Quiz</h1>
      <p class="intro">Choose every answer that applies for each question, then submit your responses.</p>
      <form id="quiz-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="language-types-help">
            <legend>1. Which of these are programming languages?</legend>
            <p class="help-text" id="language-types-help">Select all options that are commonly used to write executable software.</p>
            <div class="choices">
              <label class="choice" for="language-types-python">
                <input id="language-types-python" name="language-types" type="checkbox" value="python" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">Python</span>
                  <span class="choice-detail">A high-level language used for web, data, scripting, and automation.</span>
                </span>
              </label>
              <label class="choice" for="language-types-javascript">
                <input id="language-types-javascript" name="language-types" type="checkbox" value="javascript" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">JavaScript</span>
                  <span class="choice-detail">A language used heavily in browsers, servers, and tooling.</span>
                </span>
              </label>
              <label class="choice" for="language-types-html">
                <input id="language-types-html" name="language-types" type="checkbox" value="html" data-correct="false">
                <span class="choice-text">
                  <span class="choice-name">HTML</span>
                  <span class="choice-detail">A markup language for structuring web content.</span>
                </span>
              </label>
              <label class="choice" for="language-types-rust">
                <input id="language-types-rust" name="language-types" type="checkbox" value="rust" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">Rust</span>
                  <span class="choice-detail">A systems programming language focused on safety and performance.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which languages can run natively in modern web browsers?</legend>
            <div class="choices">
              <label class="choice" for="web-languages-javascript">
                <input id="web-languages-javascript" name="web-languages" type="checkbox" value="javascript" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">JavaScript</span>
                  <span class="choice-detail">The standard scripting language supported by browsers.</span>
                </span>
              </label>
              <label class="choice" for="web-languages-typescript">
                <input id="web-languages-typescript" name="web-languages" type="checkbox" value="typescript" data-correct="false">
                <span class="choice-text">
                  <span class="choice-name">TypeScript</span>
                  <span class="choice-detail">Usually compiled to JavaScript before running in browsers.</span>
                </span>
              </label>
              <label class="choice" for="web-languages-webassembly">
                <input id="web-languages-webassembly" name="web-languages" type="checkbox" value="webassembly" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">WebAssembly</span>
                  <span class="choice-detail">A low-level language format supported by modern browsers.</span>
                </span>
              </label>
              <label class="choice" for="web-languages-csharp">
                <input id="web-languages-csharp" name="web-languages" type="checkbox" value="csharp" data-correct="false">
                <span class="choice-text">
                  <span class="choice-name">C#</span>
                  <span class="choice-detail">Typically needs a runtime or compilation target for browser execution.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which of these are usually compiled before distribution?</legend>
            <div class="choices">
              <label class="choice" for="compiled-languages-go">
                <input id="compiled-languages-go" name="compiled-languages" type="checkbox" value="go" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">Go</span>
                  <span class="choice-detail">Commonly compiled into standalone binaries.</span>
                </span>
              </label>
              <label class="choice" for="compiled-languages-c">
                <input id="compiled-languages-c" name="compiled-languages" type="checkbox" value="c" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">C</span>
                  <span class="choice-detail">Traditionally compiled into machine code.</span>
                </span>
              </label>
              <label class="choice" for="compiled-languages-ruby">
                <input id="compiled-languages-ruby" name="compiled-languages" type="checkbox" value="ruby" data-correct="false">
                <span class="choice-text">
                  <span class="choice-name">Ruby</span>
                  <span class="choice-detail">Most often run by an interpreter.</span>
                </span>
              </label>
              <label class="choice" for="compiled-languages-swift">
                <input id="compiled-languages-swift" name="compiled-languages" type="checkbox" value="swift" data-correct="true">
                <span class="choice-text">
                  <span class="choice-name">Swift</span>
                  <span class="choice-detail">Commonly compiled for Apple platforms and server apps.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit quiz</button>
          <p class="result" id="quiz-result" role="status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    document.querySelector("#quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const fields = Array.from(document.querySelectorAll(".form-field"));
      const score = fields.reduce((total, field) => {
        const choices = Array.from(field.querySelectorAll('input[type="checkbox"]'));
        const selected = choices.filter((choice) => choice.checked);
        const correct = choices.filter((choice) => choice.dataset.correct === "true");
        const isCorrect =
          selected.length === correct.length &&
          selected.every((choice) => choice.dataset.correct === "true");

        return total + (isCorrect ? 1 : 0);
      }, 0);

      document.querySelector("#quiz-result").textContent = `You scored ${score} out of ${fields.length}.`;
    });
  </script>
</body>
</html>
