<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a31;
      --panel-strong: #18223d;
      --text: #f6f8ff;
      --muted: #b8c2d8;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --success: #86efac;
      --border: #31405f;
      --focus: #facc15;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.4);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(56, 189, 248, 0.24), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(129, 140, 248, 0.2), transparent 32rem),
        var(--bg);
    }

    main {
      width: min(100% - 2rem, 58rem);
      margin: 0 auto;
      padding: 4rem 0;
    }

    .quiz-card {
      padding: clamp(1.25rem, 3vw, 2.5rem);
      border: 1px solid rgba(125, 211, 252, 0.2);
      border-radius: 1.5rem;
      background: rgba(18, 26, 49, 0.88);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: 0.84rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 4rem);
      line-height: 1.05;
    }

    .intro {
      max-width: 42rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.08rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: linear-gradient(180deg, rgba(24, 34, 61, 0.96), rgba(18, 26, 49, 0.96));
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      float: left;
      width: 100%;
      margin-bottom: 0.35rem;
      font-size: 1.18rem;
      font-weight: 800;
    }

    .help-text {
      clear: both;
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .choices {
      clear: both;
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .choice {
      display: flex;
      gap: 0.75rem;
      align-items: flex-start;
      padding: 0.9rem 1rem;
      border: 1px solid rgba(184, 194, 216, 0.22);
      border-radius: 0.85rem;
      background: rgba(11, 16, 32, 0.5);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(125, 211, 252, 0.68);
      background: rgba(56, 189, 248, 0.1);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0.12rem 0 0;
      accent-color: var(--accent-strong);
      flex: 0 0 auto;
    }

    input[type="checkbox"]:focus-visible,
    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .choice-text {
      display: grid;
      gap: 0.18rem;
    }

    .choice-name {
      font-weight: 700;
    }

    .choice-detail {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
      margin-top: 0.5rem;
    }

    button {
      min-height: 3rem;
      padding: 0.8rem 1.25rem;
      border: 0;
      border-radius: 999px;
      color: #04111f;
      background: linear-gradient(135deg, var(--accent), var(--success));
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(56, 189, 248, 0.22);
    }

    button:hover {
      filter: brightness(1.06);
    }

    .result {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 700;
